contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _minSum, uint _deposit, uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_deposit)); require(_deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= _deposit);
        require(_deposit >= _minSum);
        require(_am <= _deposit);
        require(_deposit > 0);

        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: _deposit}(); if (__ESBMC_reverted()) return;

        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!reverted && afterBal == beforeBal - _am && afterMinSum == beforeMinSum);
    }

    receive() external payable {}
}

